await Promise.allSettled([
["inventory","entire trail list --status open,draft --limit 1000 --json"],
["prs","gh pr list --repo entireio/entire-brain --state open --limit 1000 --json number,title,headRefName,baseRefName,headRefOid,isDraft,url,mergeable,mergeStateStatus,statusCheckRollup"],
["local","git worktree list --porcelain\nrg --files -g AGENTS.md -g mise.toml -g '*runner*' -g '.entire/**' -g '.github/workflows/**'\nentire api --help\nentire graph query --help"]
].map(async ([name,cmd])=>{let r=await tools.exec_command({cmd,max_output_tokens:name==="prs"?8000:7000});store(name,r.output);text({name,...r})}));

text(JSON.parse(load("inventory")).map(t=>({number:t.number,branch:t.branch,base:t.base,title:t.title,status:t.status,phase:t.phase})));
await Promise.allSettled([
["prs","gh pr list --repo entireio/entire-brain --state open --limit 1000 --json number,title,headRefName,baseRefName,headRefOid,isDraft,url,mergeable,mergeStateStatus,statusCheckRollup --jq '.[] | {number,title,headRefName,baseRefName,headRefOid,isDraft,url,mergeable,mergeStateStatus,checks:[.statusCheckRollup[] | {name,status,conclusion}]}'"],
["detail","entire trail show 249 --json\nentire api --to cell '/api/v1/repos/{repo_id}/trails/249'"],
["graph","entire graph help\nentire brain query --help"],
["fetch","git fetch origin --prune"]
].map(async ([name,cmd])=>text({name,...await tools.exec_command({cmd,max_output_tokens:6000})})));

