+	return &conflictComponents{parent: map[string]string{}}
+}
+
+func (c *conflictComponents) root(id string) string {
+	p, ok := c.parent[id]
+	if !ok {
+		c.parent[id] = id
+		return id
+	}
+	if p != id {
+		c.parent[id] = c.root(p)
+	}
+	return c.parent[id]
