	return s.Lock(func() error {
		st, err := s.Load()
		if err != nil {
			return err
		}
		if err = fn(&st); err != nil {
			return err
		}
		b, err := json.Marshal(st)
		if err != nil {
			return err
		}
		return s.Write(filepath.Join(s.Root, "state.json"), b)
	})
}
