// edit cannot reintroduce a porcelain worktree diff there.
func TestNoPorcelainWorktreeDiffRemainsInTheBriefPath(t *testing.T) {
	t.Parallel()

	data, err := os.ReadFile("semantic.go")
	if err != nil {
