// writeCappedHistoryFixture lays down a brain whose raw history trips
// regressionScanHistory's distinct-signal cap inside the FIRST file, so the
// second file (which carries a real, distinct invariant) is never opened.
func writeCappedHistoryFixture(t *testing.T) string {
	t.Helper()
	brainDir := t.TempDir()
	sessDir := filepath.Join(brainDir, "sessions")
	if err := os.MkdirAll(sessDir, 0o755); err != nil {
		t.Fatal(err)
	}
	var bulk strings.Builder
	for i := 0; i < 420; i++ {
		// change signal: identifier adjacent to a distinctive literal operand
		fmt.Fprintf(&bulk, `{"text":"the range must stay scopeBaseRef+\"oprnd%04d\" here"}`+"\n", i)
		// delete signal: a field assignment whose target contains the identifier
		fmt.Fprintf(&bulk, `{"text":"keep state.scopeBaseRef = rhsval%04d after the update"}`+"\n", i)
	}
	if err := os.WriteFile(filepath.Join(sessDir, "a_bulk.jsonl"), []byte(bulk.String()), 0o644); err != nil {
		t.Fatal(err)
	}
	tail := `{"text":"in pkg/review_context.go the scope diff uses scopeBaseRef+\"..HEAD\" for the range"}` + "\n"
	if err := os.WriteFile(filepath.Join(sessDir, "z_tail.jsonl"), []byte(tail), 0o644); err != nil {
		t.Fatal(err)
	}
	return brainDir
}

// Bug 1: the raw-history walk stops at a hard cap via filepath.SkipAll and says
// nothing, so "No suspected regressions" is printed over a PARTIAL scan.
func TestRegressionHistoryScanCapIsSurfacedNotSilent(t *testing.T) {
	brainDir := writeCappedHistoryFixture(t)
	repoRoot := t.TempDir()
	full := filepath.Join(repoRoot, "pkg", "review_context.go")
	if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
		t.Fatal(err)
	}
	// Current tree LOST the invariant that only the un-scanned tail file records.
	if err := os.WriteFile(full, []byte("package x\nfunc f() string {\n\treturn \"master..HEAD\"\n}\n"), 0o644); err != nil {
		t.Fatal(err)
	}

	_, _, warnings := detectRegressionAnomalies(brainDir, repoRoot, nil, "fix scopeBaseRef base scope", 20, false)
	found := false
	for _, w := range warnings {
		if strings.Contains(w, "stopped early") && strings.Contains(w, "partial") {
			found = true
		}
	}
	if !found {
		t.Fatalf("capped history scan must warn that the result is partial; warnings = %q", warnings)
	}

	// The headline may not read as a clean bill of health over a truncated scan.
	if line := regressionNoAnomaliesLine("q", 5, true); strings.HasPrefix(line, "No suspected regressions") {
		t.Fatalf("truncated scan must not print the unqualified headline: %q", line)
	}
	if line := regressionNoAnomaliesLine("q", 5, false); !strings.HasPrefix(line, "No suspected regressions") {
		t.Fatalf("a complete scan with no findings must keep the plain headline: %q", line)
	}
}

// Bug 2: usefulExportWarnings drops whole classes of warning unless --debug and
// the printed count describes the FILTERED set, so an export with unreadable
// checkpoint snapshots reads as complete.
func TestExportWarningSuppressionIsDisclosed(t *testing.T) {

// regressionSeverity maps detector confidence to a review severity. Every finding the current
// heuristic detector emits is *suspected* — `changed` (0.8) is precise but rename-ambiguous and
// `deleted` (0.65) is noisier/opt-in — so none warrant "high". That tier is reserved for a future
// high-confidence signal (a durable fact bound to a locus with recency), so the machine severity
// never contradicts the "could be a rename — verify" hedge: changed -> medium, deleted -> low.
func regressionSeverity(conf float64) string {
	switch {
	case conf >= 0.9:
		return "high" // reserved: no heuristic finding reaches this today
	case conf >= 0.7:
		return "medium"
	default:
		return "low"
	}
}

// regressionNoAnomaliesLine is the headline `inspect regressions` prints when nothing was
// flagged. Like reviewSummary, it may never claim more than the run established.
//
// There are three distinct causes of zero findings and they used to share two sentences:
//   - scanned == 0: nothing was compared at all.
//   - the raw-history walk hit a file or signal cap and abandoned the rest of the brain: the
//     comparison that did run was over a PREFIX of history. "No suspected regressions" read as a
//     clean bill of health for evidence that was never opened.
//   - the scan completed: the only case that earns the unqualified sentence.
func regressionNoAnomaliesLine(query string, scanned int, historyTruncated bool) string {
	switch {
	case scanned == 0:
		return fmt.Sprintf("INCONCLUSIVE for %q: nothing was compared (0 files scanned).", query)
	case historyTruncated:
		return fmt.Sprintf("PARTIAL for %q: nothing flagged in what was compared (scanned %d files), but the history scan stopped at a cap before the end of the brain, so this is not a clean bill of health (see the notes below).", query, scanned)
	default:
		return fmt.Sprintf("No suspected regressions for %q (scanned %d files).", query, scanned)
	}
}

// reviewSummary is the one line a reader takes away, and it may never say more
// than the run actually established.
//
// Zero findings has two completely different causes and they were reported with
// the same sentence: "no suspected regressions (current tree matches the brain's
// memory)". On a brain that was never built, or whose history holds no precise
// code assertions for the query, detectRegressionAnomalies returns before it
// opens a single file — scanned == 0 — and that sentence became a clean bill of
// health for a comparison that never happened. The contradiction was printed
// directly underneath it, as "note: history holds no precise code assertions for
// these identifiers", but the summary is the line people quote.
//
// scanned is the number of current files actually read and compared, so
// scanned == 0 is the precise, non-string-matched test for "nothing was
// checked".
func reviewSummary(findings, scanned int) string {
	switch {
	case findings > 0:
		return fmt.Sprintf("Diff-less review: %d suspected regression(s) — verify each before acting.", findings)
	case scanned == 0:
		return "Diff-less review: INCONCLUSIVE — nothing was compared (the brain holds no code assertions to check this tree against). This is not a clean result; see the notes below."
	default:
		return fmt.Sprintf("Diff-less review: no suspected regressions (%d file(s) compared against the brain's memory).", scanned)
	}
}

func anomalyToReviewFinding(a regressionAnomaly) reviewFinding {
	detail := "suspected regression at this location — verify against the brain's history."
	if a.Expected != "" {
		detail = fmt.Sprintf("history shows `%s`; current is `%s` — verify this change is intentional (could also be a rename).", a.Expected, a.Current)
	}
	return reviewFinding{
		Severity:   regressionSeverity(a.Confidence),
		File:       a.File,
		Line:       a.Line,
		Title:      fmt.Sprintf("Suspected regression: `%s` %s", a.Identifier, a.Kind),
		Detail:     detail,
		Evidence:   a.Evidence,
		Confidence: a.Confidence,
	}
}

func runBrainReview(ctx context.Context, cmd *cobra.Command, opts Options, ro regressionDetectorOptions, query string) error {
	if ro.limit <= 0 {
		ro.limit = 20
	}
	target := agentSurfaceTarget(opts, nil)
	status, err := buildBrainStatusReport(ctx, opts, target)
	if err != nil {
		return err
	}
	privacyPolicy, err := captureRetrievalPrivacyPolicy(status.Brain.Path)
	if err != nil {
		return err
	}
	if ro.patterns {
		privacyPolicy.RequireDerivedClean = true
		if err := requirePrivacyDerivedRead(status.Brain.Path); err != nil {
			return err
		}
		if err := requirePatternCorpusAvailable(status.Brain.Path); err != nil {
			return err
		}
	}
	var semSource *semanticSourceManifest
	if status.Manifest != nil && status.Manifest.Sources != nil {
		semSource = status.Manifest.Sources.Semantic
	}
	anomalies, scanned, warnings := detectRegressionAnomalies(status.Brain.Path, status.Repo.Root, semSource, query, ro.limit, ro.includeDeletions)
