func regressionScanHistoryCapped(brainDir string, ids []string) ([]changeSignal, []deleteSignal, map[string]struct{}, regressionScanCaps, error) {
	const (
		maxFiles       = 20000
		maxLineBytes   = 4 * 1024 * 1024
		maxSignalsEach = 400
	)
	caps := regressionScanCaps{MaxFiles: maxFiles, MaxSignals: maxSignalsEach}
	// Resolve excluded transcript paths before reading any history. A broken
	// manifest or privacy policy must fail closed, not disable exclusion.
	manifest, err := loadBrainManifest(brainDir)
	if err != nil {
		return nil, nil, nil, caps, err
	}
	guard, err := loadSessionReadGuard(brainDir, manifest)
	if err != nil {
		return nil, nil, nil, caps, err
	}
	lowIDs := make([]string, 0, len(ids))
	for _, id := range ids {
		lowIDs = append(lowIDs, strings.ToLower(id))
	}
	var changes []changeSignal
	var deletes []deleteSignal
	files := map[string]struct{}{}
	seenC := map[string]int{}
	seenD := map[string]int{}
	scanned := 0
	_ = filepath.WalkDir(brainDir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if d.IsDir() {
			if n := d.Name(); n == semanticDirName || n == ".git" {
				return filepath.SkipDir
			}
			return nil
		}
		// Record WHICH cap fired before abandoning the walk. Stopping silently here is what let
		// "No suspected regressions" be printed over a scan that never finished.
		if scanned >= maxFiles {
			caps.FileCap = true
		}
		if len(seenC) >= maxSignalsEach && len(seenD) >= maxSignalsEach {
			caps.SignalCap = true
		}
		if caps.FileCap || caps.SignalCap {
			return filepath.SkipAll
		}
		switch filepath.Ext(path) {
		case ".jsonl", ".json", ".md", ".txt":
		default:
			return nil
		}
		rel, _ := filepath.Rel(brainDir, path)
		relSlash := filepath.ToSlash(rel)
		if brainRawScanSkipsDerived(relSlash) {
			return nil
		}
		if _, excluded := guard.paths[relSlash]; excluded {
			return nil
		}
		f, openErr := os.Open(path)
		if openErr != nil {
			return nil
		}
		scanned++
		sc := bufio.NewScanner(f)
		sc.Buffer(make([]byte, 0, 64*1024), maxLineBytes)
		lineNo := 0
		for sc.Scan() {
			lineNo++
			line := sc.Text()
			low := strings.ToLower(line)
			matched := false
			for _, id := range lowIDs {
				if !strings.Contains(low, id) {
					continue
				}
				matched = true
