// defaultRefreshAgent picks the agent that will read session transcripts.
//
// ollama is tried FIRST, and that ordering is the point of issue #328. It was
// absent from this list entirely, so a user who had installed a local model
// specifically to keep transcripts off a third party got one of two outcomes:
// "none", and silently no distillation at all, or -- if they also happened to
// have codex or claude installed -- their session content sent to a cloud
// provider instead. Neither is what installing ollama asked for.
//
// Transcripts are the most sensitive thing this product touches. When a local
// model is available, preferring it is the behaviour the user configured, and
// the only one that needs no explanation afterwards.
//
// This does change the agent for someone who has both ollama and a cloud CLI
// installed. --agent still overrides it per run.
func defaultRefreshAgent(ctx context.Context, runner CommandRunner, repoDir string) string {
	if brainNoEgressMode() {
		return "none"
	}
	// Ollama is preferred ONLY when a model is actually named.
	//
	// The preference above is right and deliberate: transcripts are the most
	// sensitive thing this product touches, and a user who installed a local
	// model asked for it to be used. But execOllamaDistillAgent hard-errors
	// with "--agent ollama requires --model", and no model is resolved here --
	// so merely having ollama ON PATH made every agent-backed command fail:
	// distill, refresh, watch --distill, remember without --path, and
	// recall --expand. `ollama --version` succeeds with no server and no
	// models pulled, so installing it was enough to break them.
	//
	// AUTO selection can never supply that model. The distill path reads it
	// from --model alone (distill_cmd.go takes args[1]); the only ollama
	// environment variable, ENTIRE_BRAIN_OLLAMA_MODEL, is read by the
	// EMBEDDING path and does nothing here. So "auto -> ollama" is a state
	// that cannot work, whatever else is configured.
	//
	// A model is NOT auto-picked instead. `ollama list` routinely offers
	// nomic-embed-text, an EMBEDDING model that would return nonsense for
	// distillation; choosing one is a product decision, not a default worth
	// guessing.
	//
	// Ollama is still fully available EXPLICITLY -- `--agent ollama --model
	// <name>` is unaffected. What is removed is only the automatic choice that
	// then failed. The caller warns when it falls through, so a
	// privacy-motivated install does not quietly become a cloud call.
	if commandLooksAvailable(ctx, runner, repoDir, "codex") {
		return "codex"
	}
	if commandLooksAvailable(ctx, runner, repoDir, "claude") {
		return "claude-code"
	}
	return "none"
}

// ollamaModelMissingWarning is the line a caller prints when ollama is present
// but unusable, so a privacy-motivated install does not quietly become a cloud
// call.
func ollamaModelMissingWarning(ctx context.Context, runner CommandRunner, repoDir, chosen string) string {
	if chosen == "ollama" || chosen == "none" {
		return ""
	}
	if !commandLooksAvailable(ctx, runner, repoDir, "ollama") {
		return ""
	}
	return "ollama is installed but cannot be chosen automatically (it needs --model), so " + chosen +
		" was used; run with `--agent ollama --model <name>` to keep transcripts local"
}

func commandLooksAvailable(ctx context.Context, runner CommandRunner, repoDir, name string) bool {
	if runner == nil {
		return false
	}
	runCtx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	_, _, err := runner.Run(runCtx, repoDir, name, "--version")
	return err == nil
}
package cli

import (
	"context"
	"strings"
	"testing"
)

type fakeWhichRunner struct{ present map[string]bool }

func (f fakeWhichRunner) Run(ctx context.Context, dir, name string, args ...string) ([]byte, []byte, error) {
	if len(args) > 0 && f.present[args[0]] {
		return []byte("/usr/local/bin/" + args[0] + "\n"), nil, nil
	}
	if f.present[name] {
		return []byte("ok\n"), nil, nil
	}
	return nil, nil, context.Canceled
}

// `auto` used to resolve to ollama whenever the binary was on PATH, but
// execOllamaDistillAgent hard-errors with "--agent ollama requires --model"
// and auto has no model to give: the distill path reads it from --model alone,
// and ENTIRE_BRAIN_OLLAMA_MODEL is the EMBEDDING path's variable, not this one.
//
// So merely installing ollama broke distill, refresh, watch --distill,
// remember without --path, and recall --expand. `ollama --version` succeeds
// with no server and no models pulled, so installation alone was enough.
func TestAutoNeverResolvesToOllama(t *testing.T) {
	t.Parallel()

	ctx := context.Background()
	all := fakeWhichRunner{present: map[string]bool{"ollama": true, "codex": true, "claude": true}}
	if got := defaultRefreshAgent(ctx, all, t.TempDir()); got == "ollama" {
		t.Error("auto must not choose ollama: it cannot supply the --model ollama requires")
	}

	// It still chooses a working agent rather than giving up.
	if got := defaultRefreshAgent(ctx, all, t.TempDir()); got != "codex" {
		t.Errorf("auto should fall through to the next usable agent, got %q", got)
	}
	onlyClaude := fakeWhichRunner{present: map[string]bool{"ollama": true, "claude": true}}
	if got := defaultRefreshAgent(ctx, onlyClaude, t.TempDir()); got != "claude-code" {
		t.Errorf("with only claude beside ollama, want claude-code, got %q", got)
	}
	// Nothing usable is still "none", not ollama.
	onlyOllama := fakeWhichRunner{present: map[string]bool{"ollama": true}}
	if got := defaultRefreshAgent(ctx, onlyOllama, t.TempDir()); got != "none" {
		t.Errorf("ollama alone cannot distill automatically, want none, got %q", got)
	}
}

// Falling through must not be silent: a user who installed ollama for privacy
// needs to know a cloud agent ran instead, and how to get the local one.
func TestFallingBackFromOllamaIsDisclosed(t *testing.T) {
	t.Parallel()

	ctx := context.Background()
	all := fakeWhichRunner{present: map[string]bool{"ollama": true, "codex": true}}

	warn := ollamaModelMissingWarning(ctx, all, t.TempDir(), "codex")
	for _, want := range []string{"ollama", "--model", "codex"} {
		if !strings.Contains(warn, want) {
			t.Errorf("the warning must mention %q: %q", want, warn)
		}
	}

	// No warning when ollama was actually used, when nothing ran, or when
	// ollama is not installed at all -- otherwise it is noise.
	if got := ollamaModelMissingWarning(ctx, all, t.TempDir(), "ollama"); got != "" {
		t.Errorf("no warning when ollama was chosen: %q", got)
	}
	if got := ollamaModelMissingWarning(ctx, all, t.TempDir(), "none"); got != "" {
		t.Errorf("no warning when no agent ran: %q", got)
	}
	noOllama := fakeWhichRunner{present: map[string]bool{"codex": true}}
	if got := ollamaModelMissingWarning(ctx, noOllama, t.TempDir(), "codex"); got != "" {
		t.Errorf("no warning when ollama is not installed: %q", got)
	}
}
package cli

import (
	"context"
	"strings"
	"testing"
)

// availabilityRunner reports a fixed set of commands as present on PATH.
type availabilityRunner struct{ present map[string]bool }

// commandLooksAvailable probes with Run(ctx, dir, <command>, "--version"), so
// the command is the NAME argument, not one of args.
func (a *availabilityRunner) Run(ctx context.Context, dir, name string, args ...string) ([]byte, []byte, error) {
	if a.present[name] {
		return []byte(name + " 1.0.0\n"), nil, nil
	}
	return nil, nil, context.Canceled
}

// Issue #328: a user who installed a local model to keep transcripts off a
// third party got either no distillation at all, or -- if a cloud CLI happened
// to be installed too -- their sessions sent to that provider instead.
//
// AMENDED. The original fix preferred ollama whenever the binary was on PATH,
// and that premise does not hold: AUTO selection cannot supply the --model
// that execOllamaDistillAgent requires (the distill path reads it from the
// flag alone; ENTIRE_BRAIN_OLLAMA_MODEL belongs to the embedding path). So
// "auto -> ollama" did not keep transcripts local -- it returned
// "distill: --agent ollama requires --model" and nobody got distillation at
// all. Installing ollama was enough to break distill, refresh,
// watch --distill, remember without --path and recall --expand.
//
// Auto therefore selects an agent that can actually run, and the concern
// behind #328 -- sessions going to a cloud provider SILENTLY -- is covered by
// ollamaModelMissingWarning, which names the fallback and how to get the local
// path back. Explicit `--agent ollama --model <name>` is unchanged.
//
// A model is not auto-picked: `ollama list` routinely offers an embedding
// model such as nomic-embed-text, which would return nonsense for
// distillation. Choosing one is a product decision, not a default.
func TestLocalModelIsPreferredOverACloudAgent(t *testing.T) {
	t.Parallel()

	for name, tc := range map[string]struct {
		present []string
		want    string
	}{
		// Ollama alone cannot distill automatically, so auto reports none
		// rather than selecting an agent that will error.
		"ollama alone cannot be auto-selected":   {[]string{"ollama"}, "none"},
		"codex runs when ollama has no model":    {[]string{"ollama", "codex"}, "codex"},
		"claude runs when ollama has no model":   {[]string{"ollama", "claude"}, "claude-code"},
		"codex still used when ollama is absent": {[]string{"codex"}, "codex"},
		"claude still used as the last resort":   {[]string{"claude"}, "claude-code"},
		"nothing installed means none":           {nil, "none"},
	} {
		t.Run(name, func(t *testing.T) {
			present := map[string]bool{}
			for _, c := range tc.present {
				present[c] = true
			}
			got := defaultRefreshAgent(context.Background(), &availabilityRunner{present: present}, t.TempDir())
			if got != tc.want {
				t.Fatalf("with %v installed, chose %q, want %q", tc.present, got, tc.want)
			}
		})
	}
}

// The watcher runs unattended on a timer, so a hardcoded cloud agent there
// sends transcripts off the machine without the user ever choosing it. The
// sentinel must be the one runDistill actually resolves: "auto", not "".
func TestWatchDefaultsToDetectionNotAHardcodedCloudAgent(t *testing.T) {
	t.Parallel()

	got := defaultWatchOptions().distillAgent
	if got == "codex" || got == "claude-code" {
		t.Fatalf("the watcher hardcodes the cloud agent %q (#328)", got)
	}
	if got != "auto" {
		t.Fatalf("watch distill agent is %q; only \"auto\" is resolved through defaultRefreshAgent, "+
			"anything else is passed through as an agent name", got)
	}
	// Non-vacuity: prove "auto" is really the sentinel the distill path reads.
	src := readSourceForTest(t, "distill_cmd.go")
	if !strings.Contains(src, `distillOpts.agent == "auto"`) {
		t.Fatal("distill no longer resolves the \"auto\" sentinel; the watcher default would pass through unresolved")
	}
}
