// seedSymbolKinds builds a minimal symbols table with the given kind:count
// shape, so the inventory can be checked against a known truth.
func seedSymbolKinds(t *testing.T, counts map[string]int) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "semantic.db")
	db, err := sql.Open(sqliteDriverName, path)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer db.Close()
	if _, err := db.Exec(`CREATE TABLE symbols (kind TEXT, name TEXT)`); err != nil {
		t.Fatalf("create: %v", err)
	}
	for kind, n := range counts {
		for i := 0; i < n; i++ {
			if _, err := db.Exec(`INSERT INTO symbols (kind, name) VALUES (?, ?)`, kind, fmt.Sprintf("%s%d", kind, i)); err != nil {
				t.Fatalf("insert: %v", err)
			}
		}
	}
	return path
}

// total summed only the rows returned by LIMIT 6, so with more than six
// distinct kinds it under-reported -- a partial sum of the top groups, not the
// real total.
//
// This note exists to give an agent an accurate picture after an empty result.
// A too-low total risks the same false root cause the note was written to
// prevent, which is the mistake that prompted writing it in the first place.
func TestKindInventoryTotalCountsEveryKindNotJustTheTopSix(t *testing.T) {
	t.Parallel()

	// Nine kinds, one symbol each: six are displayed, all nine must be counted.
	counts := map[string]int{}
	for i := 0; i < 9; i++ {
		counts[fmt.Sprintf("kind%d", i)] = 1
	}
	path := seedSymbolKinds(t, counts)

	total, distinct, kinds := semanticIndexKindInventory(path)
	if total != 9 {
		t.Errorf("total = %d, want 9: the total must count every symbol, not only the displayed groups", total)
	}
	if distinct != 9 {
		t.Errorf("distinct kinds = %d, want 9", distinct)
	}
	if len(kinds) != 6 {
		t.Errorf("displayed kinds = %d, want 6 (the list stays bounded)", len(kinds))
	}
}

// With six or fewer kinds the numbers are unchanged, so the fix cannot be
// passing by inflating every count.
func TestKindInventoryIsExactBelowTheDisplayLimit(t *testing.T) {
	t.Parallel()

	path := seedSymbolKinds(t, map[string]int{"func": 5, "type": 3, "method": 2})
	total, distinct, kinds := semanticIndexKindInventory(path)
	if total != 10 {
		t.Errorf("total = %d, want 10", total)
	}
	if distinct != 3 || len(kinds) != 3 {
		t.Errorf("distinct=%d displayed=%d, want 3 and 3", distinct, len(kinds))
	}
}

// A truncated list must say it is truncated: six of nine kinds presented as the
// whole set is the same misdirection as an under-reported total.
func TestEmptySymbolNoteDisclosesATruncatedKindList(t *testing.T) {
	t.Parallel()

	counts := map[string]int{}
	for i := 0; i < 9; i++ {
		counts[fmt.Sprintf("kind%d", i)] = 1
	}
	path := seedSymbolKinds(t, counts)

	var out bytes.Buffer
	cmd := &cobra.Command{}
	cmd.SetOut(&out)
	printSemanticNoSymbolMatch(cmd, path, "someSymbol")

	got := out.String()
	if !strings.Contains(got, "holds 9 symbols") {
		t.Errorf("the note must report the true total:\n%s", got)
	}
	if !strings.Contains(got, "6 of 9 kinds") {
		t.Errorf("the note must say the kind list is partial:\n%s", got)
	}
}

// And with nothing truncated it must not add the parenthetical, or the note
// becomes noise on the common case.
func TestEmptySymbolNoteOmitsTheCountWhenNothingIsTruncated(t *testing.T) {
	t.Parallel()

	path := seedSymbolKinds(t, map[string]int{"func": 2, "type": 1})
	var out bytes.Buffer
	cmd := &cobra.Command{}
	cmd.SetOut(&out)
	printSemanticNoSymbolMatch(cmd, path, "someSymbol")

	if got := out.String(); strings.Contains(got, "of 2 kinds") {
		t.Errorf("nothing was truncated, so the note must not say it was:\n%s", got)
	}
}
package agentsetup

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// A brain nothing reads is the product's worst failure mode, and it is SILENT:
// setup succeeds, every source reads healthy, and no agent consults the brain
// because nothing told it the brain exists. The published guide teaches
// `setup` then `status` without `init-agents`, so a reader following it lands
// here by default and concludes the product does not work.
func TestAgentsWiredDetectsAnUnwiredRepository(t *testing.T) {
	t.Parallel()

	// Nothing installed: both halves missing.
	bare := t.TempDir()
	wired, missing := AgentsWired(bare)
	if wired {
		t.Error("a repository with no guide and no pointer is not wired")
	}
	if len(missing) != 2 {
		t.Errorf("both halves should be named, got %v", missing)
	}

	// The guide alone is not enough -- nothing points at it.
	guideOnly := t.TempDir()
	writeFile(t, filepath.Join(guideOnly, ".entire", "agent-guide.md"), "# guide\n")
	if wired, missing := AgentsWired(guideOnly); wired {
		t.Error("a guide no file points at does not wire anything")
	} else if len(missing) != 1 || !strings.Contains(missing[0], "AGENTS.md") {
		t.Errorf("the missing half should be the pointer, got %v", missing)
	}

	// A pointer with no guide is equally incomplete.
	pointerOnly := t.TempDir()
	writeFile(t, filepath.Join(pointerOnly, "CLAUDE.md"), Pointer)
	if wired, missing := AgentsWired(pointerOnly); wired {
		t.Error("a pointer at a guide that does not exist is not wired")
	} else if len(missing) != 1 || !strings.Contains(missing[0], "agent-guide.md") {
		t.Errorf("the missing half should be the guide, got %v", missing)
	}

	// Either instruction file satisfies it: they are documented aliases, and a
	// repo may legitimately keep only the one its agent reads.
	for _, name := range []string{"AGENTS.md", "CLAUDE.md"} {
		root := t.TempDir()
		writeFile(t, filepath.Join(root, ".entire", "agent-guide.md"), "# guide\n")
		writeFile(t, filepath.Join(root, name), Pointer)
		if wired, missing := AgentsWired(root); !wired {
			t.Errorf("%s alone should satisfy the pointer, missing=%v", name, missing)
		}
	}

	// A file that exists but carries someone's own text, not the managed
	// block, does not count.
	unmanaged := t.TempDir()
	writeFile(t, filepath.Join(unmanaged, ".entire", "agent-guide.md"), "# guide\n")
	writeFile(t, filepath.Join(unmanaged, "AGENTS.md"), "# my own instructions\n")
	if wired, _ := AgentsWired(unmanaged); wired {
		t.Error("an AGENTS.md without the managed block does not point at the guide")
	}

	// No root is not a claim either way, and must not report "wired".
	if wired, _ := AgentsWired(""); wired {
		t.Error("an empty root must not report wired")
	}
}

func writeFile(t *testing.T, path, content string) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
}
